import sys
from scanner import scan_ports
from web import web_recon
from report import save_csv, save_json

def parse_args(): ...
def main():
    target, ports, fmt, output = parse_args()
    results = scan_ports(target, ports[0], ports[1])
    for r in results:
        if r['port'] in [80,443]:
            r['web'] = web_recon(target, r['port'], use_ssl=(r['port']==443))
    if fmt == 'csv': save_csv(results, output)
    else: save_json(results, output)
    print('Done.')
if __name__ == '__main__':
    main()
